import{_ as d,o as a,c as e,a2 as r}from"./chunks/framework.CmvPqeTF.js";const f=JSON.parse('{"title":"使用指南总览","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md","lastUpdated":1791351888000}'),h={name:"guide/index.md"};function o(i,t,l,s,n,c){return a(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="使用指南总览" tabindex="-1">使用指南总览 <a class="header-anchor" href="#使用指南总览" aria-label="Permalink to &quot;使用指南总览&quot;">​</a></h1><p>vShell 是一个<strong>纯本地</strong>的桌面 SSH 客户端管理工具（类似 FinalShell），基于 Wails 3（Go 后端 + Vue 3 前端）构建。没有云端组件、没有账号体系、没有遥测——你的所有数据都保存在本机，敏感信息经 AES-256-GCM 加密后存储。</p><h2 id="功能矩阵" tabindex="-1">功能矩阵 <a class="header-anchor" href="#功能矩阵" aria-label="Permalink to &quot;功能矩阵&quot;">​</a></h2><table tabindex="0"><thead><tr><th>功能</th><th>说明</th><th>文档</th></tr></thead><tbody><tr><td>连接管理</td><td>分组树形组织、拖拽调整归属、密码 / 私钥 / 交互式认证</td><td><a href="./connections.html">连接与分组管理</a></td></tr><tr><td>SSH 密钥</td><td>生成、导入、管理密钥对</td><td><a href="./keys.html">SSH 密钥管理</a></td></tr><tr><td>~/.ssh/config</td><td>结构化编辑、导入为连接</td><td><a href="./ssh-config.html">导入导出</a></td></tr><tr><td>终端</td><td>xterm.js PTY 终端、复制粘贴、断线重连</td><td><a href="./terminal.html">终端使用</a></td></tr><tr><td>远程编辑</td><td>Monaco Editor 编辑远程文件</td><td><a href="./editor.html">远程文件编辑</a></td></tr><tr><td>SFTP</td><td>浏览、传输、拖拽、进度跟踪</td><td><a href="./sftp.html">SFTP 文件管理</a></td></tr><tr><td>服务器监控</td><td>CPU / 内存 / 磁盘 / 进程 / 网络实时图表</td><td><a href="./monitor.html">服务器监控</a></td></tr><tr><td>端口转发</td><td>本地端口转发、服务预设</td><td><a href="./port-forwarding.html">端口转发</a></td></tr><tr><td>HTTPS 证书</td><td>acme.sh 远程签发 / 续签、DNS 提供商配置、日志可追溯</td><td><a href="./certificates.html">HTTPS 证书管理</a></td></tr><tr><td>个性化</td><td>中英双语、主题、终端配色等</td><td><a href="./settings.html">设置与主题</a></td></tr></tbody></table><h2 id="数据安全" tabindex="-1">数据安全 <a class="header-anchor" href="#数据安全" aria-label="Permalink to &quot;数据安全&quot;">​</a></h2><ul><li>所有数据存储在本地 SQLite 数据库（macOS 位于 <code>~/Library/Application Support/vshell/vshell.db</code>）</li><li>密码、私钥、口令、DNS API 凭据等敏感字段使用 AES-256-GCM 加密后落库，绝不存明文</li><li>不联网上报任何信息</li></ul><h2 id="环境要求" tabindex="-1">环境要求 <a class="header-anchor" href="#环境要求" aria-label="Permalink to &quot;环境要求&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>要求</th></tr></thead><tbody><tr><td>操作系统</td><td>macOS / Windows / Linux（自 v0.2.0 起提供三平台安装包，见<a href="./getting-started.html">快速开始</a>）</td></tr><tr><td>Go / Node.js / pnpm</td><td>仅从源码构建时需要（Go 1.25+、Node 20+、pnpm）</td></tr></tbody></table><h2 id="反馈与问题追踪" tabindex="-1">反馈与问题追踪 <a class="header-anchor" href="#反馈与问题追踪" aria-label="Permalink to &quot;反馈与问题追踪&quot;">​</a></h2><p>开发过程中的问题记录见仓库 <code>docs/issues/</code> 目录（含模板 <code>_TEMPLATE.md</code>），可在 <a href="https://github.com/crazy-airhead/vshell/issues" target="_blank" rel="noreferrer">GitHub Issues</a> 提交新问题。</p>',10)])])}const u=d(h,[["render",o]]);export{f as __pageData,u as default};
